@article{Zhong_2025, title={Advancing Medical Multimodal Learning and Data Generation with Diffusion Model and LLM}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35237}, DOI={10.1609/aaai.v39i28.35237}, abstractNote={Synthesizing electronic health records (EHR) is essential for addressing data scarcity, bias, and fairness in healthcare models. EHR data are inherently multimodal and sequential, encompassing structured codes, clinical notes, medical
images, and irregular time intervals. Traditional generative models like GANs and VAEs struggle to capture these complexities, while diffusion-based models offer improvements but remain limited to task-specific applications. To address these challenges, two diffusion-based models, MedDiffusion and EHRPD, have been developed. MedDiffusion enhances health risk prediction by generating synthetic patient data
and capturing visit-level relationships, while EHRPD generates sequential, multimodal EHR data, incorporating temporal interval estimation to improve diversity and fidelity. Future work aims to overcome limitations in multimodal data generation by developing a generalized model capable of handling diverse modalities simultaneously, expanding the applicability of EHR data generation across healthcare tasks.}, number={28}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhong, Yuan}, year={2025}, month={Apr.}, pages={29319-29320} }

@article{Gong_Yue_Xu_2025, title={An Optimal Transport-based Latent Mixer for Robust Multi-modal Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33849}, DOI={10.1609/aaai.v39i16.33849}, abstractNote={Multi-modal learning aims to learn predictive models based on the data from different modalities. However, due to the requirement of data security and privacy protection, real-world multi-modal data are often scattered to different agents and cannot be shared across the agents, which limits the application of existing multi-modal learning methods.
To achieve robust multi-modal learning in such a challenging scenario, we propose a novel optimal transport-based mixer (OTM), which works as an effective latent code alignment and augmentation method for unaligned and distributed multi-modal data. In particular, we train a Wasserstein autoencoder (WAE) for each agent, which encodes its single modal samples in a latent space. Through a central server, the proposed OTM computes a stochastic fused Gromov-Wasserstein barycenter (FGWB) to mix different modalities’ latent codes, so that each agent applies the barycenter to reconstruct its samples.
This method neither requires well-aligned multi-modal data nor assumes the data to share the same latent distribution, and each agent can learn a specific model based on multi-modal data while achieving inference based on its local modality. Experiments on multi-modal clustering and classification demonstrate that the models learned with the OTM method outperform the corresponding baselines.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gong, Fengjiiao and Yue, Angxiao and Xu, Hongteng}, year={2025}, month={Apr.}, pages={16826-16834} }

@article{Cheng_Chen_Zhang_Fei_Feng_Che_Li_Qin_2025, title={CoMT: A Novel Benchmark for Chain of Multi-modal Thought on Large Vision-Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34538}, DOI={10.1609/aaai.v39i22.34538}, abstractNote={Large Vision-Language Models (LVLMs) have recently demonstrated amazing success in multi-modal tasks, including advancements in Multi-modal Chain-of-Thought (MCoT) reasoning. Despite these successes, current benchmarks still follow a traditional paradigm with multi-modal input and text-modal output, which leads to significant drawbacks such as missing visual operations and vague expressions.
Motivated by this, we introduce a novel Chain of Multi-modal Thought (CoMT) benchmark to address these limitations. Different from the traditional MCoT benchmark, CoMT requires both multi-modal input and multi-modal reasoning output, aiming to mimic human-like reasoning that inherently integrates visual operation. Specifically, CoMT consists of four categories: (1) Visual Creation, (2) Visual Deletion, (3) Visual Update, and (4) Visual Selection to comprehensively explore complex visual operations and concise expression in real scenarios.
We evaluate various LVLMs and strategies on CoMT, revealing some key insights into the capabilities and limitations of the current approaches. We hope that CoMT can inspire more research on introducing multi-modal generation into the reasoning process.}, number={22}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Cheng, Zihui and Chen, Qiguang and Zhang, Jin and Fei, Hao and Feng, Xiaocheng and Che, Wanxiang and Li, Min and Qin, Libo}, year={2025}, month={Apr.}, pages={23678-23686} }

@article{Jiang_Zhang_Liang_Zhou_Yang_Wu_Guan_Ding_Sheng_2025, title={Collaborative Similarity Fusion and Consistency Recovery for Incomplete Multi-view Clustering}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33937}, DOI={10.1609/aaai.v39i17.33937}, abstractNote={As partial samples are often absent in certain views, incomplete multi-view clustering has become a challenging task. To tackle data with missing views, current methods either utilize the data similarity relations to recover missing samples or primarily consider the available information of existing samples, typically facing some inherent limitations. Firstly, traditional solutions cannot fully explore the potential information contained in missing samples due to their omission strategy, leading to sub-optimal graphs. Moreover, most methods mainly focus on data recovery from the view level, ignoring the differences among available/missing samples in various views. To this end, we propose a collaborative Similarity Fusion and Consistency Recovery (SFCR) method, which resolves the incomplete multi-view clustering problem by learning a unified similarity graph and recovering missing samples with consistent structures.
Specifically, to learn a reliable graph compatible across views, a novel view-to-sample fusion model is designed to adaptively coalesce the view-wise similarities among available samples, not only preserving the complementarity and consistency among views but also properly balancing different samples.
Furthermore, the missing samples are effectively recovered under the guidance of the fused similarity graph, so as to maintain the consistent structure of recovered data across views. In this way, the similarity learning and the missing data recovery benefit from each other in a collaborative reinforcement manner. Meanwhile, SFCR can directly obtain the final clustering labels without additional post-processing. Extensive experiments demonstrate the effectiveness and superiority of SFCR.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Jiang, Bingbing and Zhang, Chenglong and Liang, Xinyan and Zhou, Peng and Yang, Jie and Wu, Xingyu and Guan, Junyi and Ding, Weiping and Sheng, Weiguo}, year={2025}, month={Apr.}, pages={17617-17625} }

@article{Huang_Xu_Liu_Liu_Han_Yuan_Li_2025, title={Densely Connected Parameter-Efficient Tuning for Referring Image Segmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32380}, DOI={10.1609/aaai.v39i4.32380}, abstractNote={In the domain of computer vision, Parameter-Efficient Tuning (PET) is increasingly replacing the traditional paradigm of pre-training followed by full fine-tuning. PET is particularly favored for its effectiveness in large foundation models, as it streamlines transfer learning costs and optimizes hardware utilization.
However, the current PET methods are mainly designed for single-modal optimization.
While some pioneering studies have undertaken preliminary explorations, they still remain at the level of aligned encoders (e.g., CLIP) and lack exploration of misaligned encoders.
These methods show sub-optimal performance with misaligned encoders, as they fail to effectively align the multimodal features during fine-tuning.
In this paper, we introduce DETRIS, a parameter-efficient tuning framework designed to enhance low-rank visual feature propagation by establishing dense interconnections between each layer and all preceding layers, which enables effective cross-modal feature interaction and adaptation to misaligned encoders. We also suggest using text adapters to improve textual features. Our simple yet efficient approach greatly surpasses state-of-the-art methods with 0.9% to 1.8% backbone parameter updates, evaluated on challenging benchmarks.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Jiaqi and Xu, Zunnan and Liu, Ting and Liu, Yong and Han, Haonan and Yuan, Kehong and Li, Xiu}, year={2025}, month={Apr.}, pages={3653-3661} }

@article{Tang_Shimada_Bi_Feng_Hua_Xu_2025, title={Empowering LLMs with Pseudo-Untrimmed Videos for Audio-Visual Temporal Understanding}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32784}, DOI={10.1609/aaai.v39i7.32784}, abstractNote={Large language models (LLMs) have demonstrated remarkable capabilities in natural language and multimodal domains. By fine-tuning multimodal LLMs with temporal annotations from well-annotated datasets, e.g., dense video captioning datasets, their temporal understanding capacity in video-language tasks can be obtained. However, there is a notable lack of untrimmed audio-visual video datasets with precise temporal annotations for events. This deficiency hinders LLMs from learning the alignment between time, audio-visual events, and text tokens, thus impairing their ability to localize audio-visual events in videos temporally.
To address this gap, we introduce PU-VALOR, a comprehensive audio-visual dataset comprising over 114,081 pseudo-untrimmed videos with detailed temporal annotations. PU-VALOR is derived from the large-scale but coarse-annotated audio-visual dataset VALOR, through a subtle method involving event-based video clustering, random temporal scaling, and permutation.
By fine-tuning a multimodal LLM on PU-VALOR, we developed AVicuna, a model capable of aligning audio-visual events with temporal intervals and corresponding text tokens. AVicuna excels in temporal localization and time-aware dialogue capabilities.
Our experiments demonstrate that AVicuna effectively handles temporal understanding in audio-visual videos and achieves state-of-the-art performance on open-ended video QA, audio-visual QA, and audio-visual event dense localization tasks.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tang, Yunlong and Shimada, Daiki and Bi, Jing and Feng, Mingqian and Hua, Hang and Xu, Chenliang}, year={2025}, month={Apr.}, pages={7293-7301} }

@article{Bo_Zhu_Li_Zhang_2025, title={FAMNet: Frequency-aware Matching Network for Cross-domain Few-shot Medical Image Segmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32184}, DOI={10.1609/aaai.v39i2.32184}, abstractNote={Existing few-shot medical image segmentation (FSMIS) models fail to address a practical issue in medical imaging: the domain shift caused by different imaging techniques, which limits the applicability to current FSMIS tasks. To overcome this limitation, we focus on the cross-domain few-shot medical image segmentation (CD-FSMIS) task, aiming to develop a generalized model capable of adapting to a broader range of medical image segmentation scenarios with limited labeled data from the novel target domain.
Inspired by the characteristics of frequency domain similarity across different domains, we propose a Frequency-aware Matching Network (FAMNet), which includes two key
components: a Frequency-aware Matching (FAM) module and a Multi-Spectral Fusion (MSF) module. The FAM module tackles two problems during the meta-learning phase: 1) intra-domain variance caused by the inherent support-query bias, due to the different appearances of organs and lesions, and 2) inter-domain variance caused by different medical imaging techniques. Additionally, we design an MSF module to integrate the different frequency features decoupled by the FAM module, and further mitigate the impact of inter-domain variance on the model’s segmentation performance.
Combining these two modules, our FAMNet surpasses existing FSMIS models and Cross-domain Few-shot Semantic Segmentation models on three cross-domain datasets, achieving state-of-the-art performance in the CD-FSMIS task.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Bo, Yuntian and Zhu, Yazhou and Li, Lunbo and Zhang, Haofeng}, year={2025}, month={Apr.}, pages={1889-1897} }

@article{Gong_Ran_Liu_Wang_Cong_Wang_Duan_Wang_2025, title={FigStep: Jailbreaking Large Vision-Language Models via Typographic Visual Prompts}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34568}, DOI={10.1609/aaai.v39i22.34568}, abstractNote={Large Vision-Language Models (LVLMs) signify a groundbreaking paradigm shift within the Artificial Intelligence (AI) community, extending beyond the capabilities of Large Language Models (LLMs) by assimilating additional modalities (e.g., images).
Despite this advancement, the safety of LVLMs remains adequately underexplored, with a potential overreliance on the safety assurances purported by their underlying LLMs. In this paper, we propose FigStep, a straightforward yet effective black-box jailbreak algorithm against LVLMs.
Instead of feeding textual harmful instructions directly, FigStep converts the prohibited content into images through typography to bypass the safety alignment.
The experimental results indicate that FigStep can achieve an average attack success rate of 82.50% on six promising open-source LVLMs.
Not merely to demonstrate the efficacy of FigStep, we conduct comprehensive ablation studies and analyze the distribution of the semantic embeddings to uncover that the reason behind the success of FigStep is the deficiency of safety alignment for visual embeddings. Moreover, we compare FigStep with five text-only jailbreaks and four image-based jailbreaks to demonstrate the superiority of FigStep, i.e., negligible attack costs and better attack performance.
Above all, our work reveals that current LVLMs are vulnerable to jailbreak attacks, which highlights the necessity of novel cross-modality safety alignment techniques.}, number={22}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gong, Yichen and Ran, Delong and Liu, Jinyuan and Wang, Conglei and Cong, Tianshuo and Wang, Anyu and Duan, Sisi and Wang, Xiaoyun}, year={2025}, month={Apr.}, pages={23951-23959} }

@article{Ning_Zhou_Wang_Huang_Huang_2025, title={GNS: Solving Plane Geometry Problems by Neural-Symbolic Reasoning with Multi-Modal LLMs}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34679}, DOI={10.1609/aaai.v39i23.34679}, abstractNote={With the outstanding capabilities of Large Language Models (LLMs), solving math word problems (MWP) has greatly progressed, achieving higher performance on several benchmark datasets. However, it is more challenging to solve plane geometry problems (PGPs) due to the necessity of understanding, reasoning and computation on two modality data including both geometry diagrams and textual questions, where Multi-Modal Large Language Models (MLLMs) have not been extensively explored.
Previous works simply regarded a plane geometry problem as multi-modal QA task, which ignored the importance of explicit parsing geometric elements from problems. To tackle this limitation, we propose to solve plane Geometry problems by Neural-Symbolic reasoning with MLLMs (GNS). We first leverage an MLLM to understand PGPs through knowledge prediction and symbolic parsing, next perform mathematical reasoning to obtain solutions, last adopt a symbolic solver to compute answers. Correspondingly, we introduce the largest PGPs dataset GNS-260K with multiple annotations including symbolic parsing, understanding, reasoning and computation. In experiments, our Phi3-Vision-based MLLM wins the first place on the PGPs solving task of MathVista benchmark, outperforming GPT-4o, Gemini Ultra and other much larger MLLMs.
While LLaVA-13B-based MLLM markedly exceeded other close-source and open-source MLLMs on the MathVerse benchmark and also achieved the new SOTA on GeoQA dataset.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ning, Maizhen and Zhou, Zihao and Wang, Qiufeng and Huang, Xiaowei and Huang, Kaizhu}, year={2025}, month={Apr.}, pages={24957-24965} }

@article{Meng_Ma_Miao_Zhang_Yang_Zhuang_2025, title={Image Regeneration: Evaluating Text-to-Image Model via Generating Identical Image with Multimodal Large Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32651}, DOI={10.1609/aaai.v39i6.32651}, abstractNote={Diffusion models have revitalized the image generation domain, playing crucial roles in both academic research and artistic expression. With the emergence of new diffusion models, assessing the performance of text-to-image models has become increasingly important.
Current metrics focus on directly matching the input text with the generated image, but due to cross-modal information asymmetry, this leads to unreliable or incomplete assessment results. Motivated by this, we introduce the Image Regeneration task in this study to assess text-to-image models by tasking the T2I model with generating an image according to the reference image.
We use GPT4V to bridge the gap between the reference image and the text input for the T2I model, allowing T2I models to understand image content.
This evaluation process is simplified as comparisons between the generated image and the reference image are straightforward. Two regeneration datasets spanning content-diverse and style-diverse evaluation dataset are introduced to evaluate the leading diffusion models currently available.
Additionally, we present ImageRepainter framework to enhance the quality of generated images by improving content comprehension via MLLM guided iterative generation and revision.
Our comprehensive experiments have showcased the effectiveness of this framework in assessing the generative capabilities of models. By leveraging MLLM, we have demonstrated that a robust T2M can produce images more closely resembling the reference image.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Meng, Chutian and Ma, Fan and Miao, Jiaxu and Zhang, Chi and Yang, Yi and Zhuang, Yueting}, year={2025}, month={Apr.}, pages={6090-6098} }

@article{Liu_Hu_Du_Zhang_Zhou_Liu_2025, title={KPL: Training-Free Medical Knowledge Mining of Vision-Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34075}, DOI={10.1609/aaai.v39i18.34075}, abstractNote={Visual Language Models such as CLIP excel in image recognition due to extensive image-text pre-training. However, applying the CLIP inference in zero-shot classification, particularly for medical image diagnosis, faces challenges due to: 1) the inadequacy of representing image classes solely with single category names; 2) the modal gap between the visual and text spaces generated by CLIP encoders. Despite attempts to enrich disease descriptions with large language models, the lack of class-specific knowledge often leads to poor performance. In addition, empirical evidence suggests that existing proxy learning methods for zero-shot image classification on natural image datasets exhibit instability when applied to medical datasets. To tackle these challenges, we introduce the Knowledge Proxy Learning (KPL) to mine knowledge from CLIP. KPL is designed to leverage CLIP’s multimodal understandings for medical image classification through Text Proxy Optimization and Multimodal Proxy Learning.
Specifically, KPL retrieves image-relevant knowledge descriptions from the constructed knowledge-enhanced base to enrich semantic text proxies.
It then harnesses input images and these descriptions, encoded via CLIP, to stably generate multimodal proxies that boost the zero-shot classification performance.
Extensive experiments conducted on both medical and natural image datasets demonstrate that KPL enables effective zero-shot image classification, outperforming all baselines. These findings highlight the great potential in this paradigm of mining knowledge from CLIP for medical image classification and broader areas.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Jiaxiang and Hu, Tianxiang and Du, Jiawei and Zhang, Ruiyuan and Zhou, Joey Tianyi and Liu, Zuozhu}, year={2025}, month={Apr.}, pages={18852-18860} }

@article{Liu_Luo_Li_Caverlee_Min_2025, title={Learning Disentangled Equivariant Representation for Explicitly Controllable 3D Molecule Generation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34071}, DOI={10.1609/aaai.v39i18.34071}, abstractNote={We consider the conditional generation of 3D drug-like molecules with explicit control over molecular properties such as drug-like properties (e.g., Quantitative Estimate of Druglikeness or Synthetic Accessibility score) and effectively binding to specific protein sites. To tackle this problem, we propose an E(3)-equivariant Wasserstein autoencoder and factorize the latent space of our generative model into two disentangled aspects: molecular properties and the remaining structural context of 3D molecules.
Our model ensures explicit control over these molecular attributes while maintaining equivariance of coordinate representation and invariance of data likelihood. Furthermore, we introduce a novel alignment-based coordinate loss to adapt equivariant networks for auto-regressive de-novo 3D molecule generation from scratch.
Extensive experiments validate our model’s effectiveness on property-guided and context-guided molecule generation, both for de-novo 3D molecule design and structure-based drug discovery against protein targets.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Haoran and Luo, Youzhi and Li, Tianxiao and Caverlee, James and Min, Martin Renqiang}, year={2025}, month={Apr.}, pages={18816-18824} }

@article{Mishra_Saha_Zhao_Hernandez-Cruz_Patey_Papageorghiou_Noble_2025, title={MCAT: Visual Query-Based Localization of Standard Anatomical Clips in Fetal Ultrasound Videos Using Multi-Tier Class-Aware Token Transformer}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35047}, DOI={10.1609/aaai.v39i27.35047}, abstractNote={Accurate standard plane acquisition in fetal ultrasound (US) videos is crucial for fetal growth assessment, anomaly detection, and adherence to clinical guidelines. However, manually selecting standard frames is time-consuming and prone to intra- and inter-sonographer variability. Existing methods primarily rely on image-based approaches that capture standard frames and then classify the input frames across different anatomies. This ignores the dynamic nature of video acquisition and its interpretation.
To address these challenges, we introduce Multi-Tier Class-Aware Token Transformer (MCAT); a visual query-based video clip localization (VQ-VCL) method to assist sonographers by enabling them to capture a quick US sweep. By then providing a visual query of the anatomy they wish to analyze, MCAT returns the video clip containing the standard frames for that anatomy, facilitating thorough screening for potential anomalies.
We evaluate MCAT on two ultrasound video datasets and a natural image VQ-VCL dataset based on Ego4D. Our model outperforms state-of-the-art methods by 10% and 13% mtIoU on the ultrasound datasets and by 5.35% mtIoU on the Ego4D dataset, using 96% fewer tokens.
MCAT’s efficiency and accuracy have significant potential implications for public health, especially in low- and middle-income countries (LMICs), where it may enhance prenatal care by streamlining standard plane acquisition, simplifying US based screening, diagnosis and allowing sonographers to examine more patients.}, number={27}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mishra, Divyanshu and Saha, Pramit and Zhao, He and Hernandez-Cruz, Netzahualcoyotl and Patey, Olga and Papageorghiou, Aris and Noble, J. Alison}, year={2025}, month={Apr.}, pages={28267-28275} }

@article{Sikdar_Teotia_Sundaram_2025, title={OGP-Net: Optical Guidance Meets Pixel-Level Contrastive Distillation for Robust Multi-Modal and Missing Modality Segmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32743}, DOI={10.1609/aaai.v39i7.32743}, abstractNote={Enhancing the performance of semantic segmentation models with multi-spectral images (RGB-IR) is crucial, particularly for low-light and adverse environments. While multi-modal fusion techniques aim to learn cross-modality features for generating fused images or engage in knowledge distillation, they often treat multi-modal and missing modality scenarios as separate challenges, which is not an optimal approach. To address this, a novel multi-modal fusion approach called Optically-Guided Pixel-level contrastive learning Network (OGP-Net) is proposed, which uses Distillation with Multi-View Contrastive (DMC) and Distillation for Uni-modal Re-
tention (DUR) to maintain the correlation between modality-shared and modality-specific features. DMC aligns the uni-modal features by projecting the semantic information across modalities into a unified latent space, ensuring that the feature maps retain multi-modal representations. Pixel-level multi-view contrastive learning is introduced to enable modality-invariant representation learning. To retain modality-specific information, DUR is proposed, which distills detailed textures from RGB images into the optical branch of OGP-Net. Additionally, the Gated Spectral Unit (GSU) is integrated into the framework to eliminate the need for manual tuning
and avoid forced feature alignment. Comprehensive experiments show that OGP-Net outperforms state-of-the-art models in multi-modal and missing modality scenarios across three public benchmarking datasets. It achieves quicker convergence and learns efficiently from limited training samples.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Sikdar, Aniruddh and Teotia, Jayant and Sundaram, Suresh}, year={2025}, month={Apr.}, pages={6922-6930} }

@article{Lu_Wang_Li_Tang_Luo_2025, title={RGBT Tracking via All-layer Multimodal Interactions with Progressive Fusion Mamba}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32618}, DOI={10.1609/aaai.v39i6.32618}, abstractNote={Existing RGBT tracking methods often design various interaction models to perform cross-modal fusion of each layer, but can not execute the feature interactions among all layers, which plays a critical role in robust multimodal representation, due to large computational burden.
To address this issue, this paper presents a novel All-layer multimodal Interaction Network, named AINet, which performs efficient and effective feature interactions of all modalities and layers in a progressive fusion Mamba, for robust RGBT tracking. Even though modality features in different layers are known to contain different cues, it is always challenging to build multimodal interactions in each layer due to struggling in balancing interaction capabilities and efficiency.
Meanwhile, considering that the feature discrepancy between RGB and thermal modalities reflects their complementary information to some extent, we design a Difference-based Fusion Mamba (DFM) to achieve enhanced fusion of different modalities with linear complexity.
When interacting with features from all layers, a huge number of token sequences (3840 tokens in this work) are involved and the computational burden is thus large. To handle this problem, we design an Order-dynamic Fusion Mamba (OFM) to execute efficient and effective feature interactions of all layers by dynamically adjusting the scan order of different layers in Mamba. Extensive experiments on four public RGBT tracking datasets show that AINet achieves leading performance against existing state-of-the-art methods.
We will release the code upon acceptance of the paper.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lu, Andong and Wang, Wanyu and Li, Chenglong and Tang, Jin and Luo, Bin}, year={2025}, month={Apr.}, pages={5793-5801} }

@article{Li_Guo_Qi_Li_Shi_2025, title={Text and Image Are Mutually Beneficial: Enhancing Training-Free Few-Shot Classification with CLIP}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32534}, DOI={10.1609/aaai.v39i5.32534}, abstractNote={Contrastive Language-Image Pretraining (CLIP) has been widely used in vision tasks. Notably, CLIP has demonstrated promising performance in few-shot learning (FSL).
However, existing CLIP-based methods in training-free FSL (i.e., without the requirement of additional training) mainly learn different modalities independently, leading to two essential issues: 1) severe anomalous match in image modality; 2) varying quality of generated text prompts.
To address these issues, we build a mutual guidance mechanism, that introduces an Image-Guided-Text (IGT) component to rectify varying quality of text prompts through image representations, and a Text-Guided-Image (TGI) component to mitigate the anomalous match of image modality through text representations.
By integrating IGT and TGI, we adopt a perspective of Text-Image Mutual guidance Optimization, proposing TIMO.
Extensive experiments show that TIMO significantly outperforms the state-of-the-art (SOTA) training-free method. Additionally, by exploring the extent of mutual guidance, we propose an enhanced variant, TIMO-S, which even surpasses the best training-required methods by 0.33% with approximately ×100 less time cost.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Yayuan and Guo, Jintao and Qi, Lei and Li, Wenbin and Shi, Yinghuan}, year={2025}, month={Apr.}, pages={5039-5047} }

@article{Wu_Chen_Wang_2025, title={Unified Knowledge Maintenance Pruning and Progressive Recovery with Weight Recalling for Large Vision-Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32923}, DOI={10.1609/aaai.v39i8.32923}, abstractNote={Large Vision-Language Model (LVLM), leveraging Large Language Model (LLM) as the cognitive core, has recently become one of the most representative multimodal model paradigms.
However, with the expansion of unimodal branches, \emph{i.e.} visual encoder and LLM, the storage and computational burdens intensify, posing challenges for deployment.
Structured pruning has proved promising in compressing large models by trimming a large portion of insignificant network structures.
Nevertheless, most of them are predominantly designed for LLMs, either relying on unitary importance metrics that fail to deal with modality-wise imbalances or adopting generic pruning and recovery paradigms that overlook the unique calibration status and capability requirements of large models, leading to substantial performance degradation.
To address these issues, we propose a novel structured pruning approach for LVLMs, dubbed Unified Knowledge Maintenance Pruning and Progressive Recovery with Weight Recalling (UKMP). Specifically, we design a Unified Knowledge Maintenance Importance (UKMI) metric, which simultaneously considers balancing the block-wise and modality-wise importance by adaptive normalization, optimizing the importance estimation by refining gradient-based criteria, and maintaining the knowledge capacity of LVLMs by using the angle distribution information entropy. Moreover, we develop a LoRA-based Progressive Distillation (LPD) method that recalls the pruned weights and performs progressive distillation for comprehensive recovery.
Extensive experimental results across various vision-language tasks demonstrate the effectiveness of our approach, comparing to the state-of-the-art structured pruning methods.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wu, Zimeng and Chen, Jiaxin and Wang, Yunhong}, year={2025}, month={Apr.}, pages={8550-8558} }

@article{Kuznetsov_Valiev_Aliper_Polykovskiy_Tutubalina_Shayakhmetov_Miftahutdinov_2025, title={nach0-pc: Multi-task Language Model with Molecular Point Cloud Encoder}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34613}, DOI={10.1609/aaai.v39i23.34613}, abstractNote={Recent advancements have integrated Language Models (LMs) into a drug discovery pipeline. However, existing models mostly work with SMILES and SELFIES chemical string representations, which lack spatial features vital for drug discovery. Additionally, attempts to translate chemical 3D structures into text format encounter issues such as excessive length and insufficient atom connectivity information.
To address these issues, we introduce nach0-pc, a model combining domain-specific encoder and textual representation to handle spatial arrangement of atoms effectively. Our approach utilizes a molecular point cloud encoder for concise and order-invariant structure representation. We introduce a novel pre-training scheme for molecular point clouds to distillate the knowledge from spatial molecular structures datasets.
After fine-tuning within both single-task and multi-task frameworks, nach0-pc demonstrates performance comparable with other diffusion models in terms of generated samples quality across several established spatial molecular generation tasks. Notably, our model is a multi-task approach, in contrast to diffusion models being limited to single tasks. Additionally, it is capable of processing point cloud-related data, which language models are not capable of handling due to memory limitations. These lead to our model having reduced training and inference time while maintaining on par performance.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Kuznetsov, Maksim and Valiev, Airat and Aliper, Alex and Polykovskiy, Daniil and Tutubalina, Elena and Shayakhmetov, Rim and Miftahutdinov, Zulfat}, year={2025}, month={Apr.}, pages={24357-24365} }
